func getInstanceShow(instance models.InstanceConfig) string {
	return fmt.Sprintf(`filters.searchQuery === '' || ('%s %s %s').toLowerCase().includes(filters.searchQuery.toLowerCase()) &&
        (filters.namePattern === '' || '%s'.toLowerCase().includes(filters.namePattern.toLowerCase())) &&
        (filters.descriptionPattern === '' || '%s'.toLowerCase().includes(filters.descriptionPattern.toLowerCase())) &&
        (filters.outputPathPattern === '' || '%s'.toLowerCase().includes(filters.outputPathPattern.toLowerCase())) &&
        (!filters.showOnlyWithImages || %d > 0 || %d > 0) &&
        (!filters.showInstancesWithoutImages || (%d === 0 && %d === 0)) &&
        (!filters.showOnlyWithErrors || '%s' !== '') &&
        (!filters.showOnlySkipped || '%s' !== '') &&
        (!filters.showOnlySuccessful || ('%s' === '' && '%s' === ''))`,
		instance.Name,
		instance.Description,
		instance.RunOutputPathV3,
		instance.Name,
		instance.Description,
		instance.RunOutputPathV3,
		len(instance.ImageResults),
		len(instance.ExportImages),
		len(instance.ImageResults),
		len(instance.ExportImages),
		instance.ConfigError,
		instance.SkippedReason,
		instance.ConfigError,
		instance.SkippedReason)
}

